import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for PrototypeObjectType#getPropertyType.
 */
public class PrototypeObjectType_getPropertyType_TriageGen2Test {

    private PrototypeObjectType prototypeObjectType;
    private JSType mockType;

    @Before
    public void setUp() {
        // We mock the class under test because getSlot is a method of the same class 
        // and we need to control its return value to test branches.
        prototypeObjectType = mock(PrototypeObjectType.class, Mockito.CALLS_REAL_METHODS);
        mockType = mock(JSType.class);
    }

    @Test
    public void testGetPropertyType_WhenSlotIsNull_ReturnsUnknownType() {
        // Arrange
        String property = "nonExistentProperty";
        // Mock getSlot to return null to trigger the first branch
        when(prototypeObjectType.getSlot(property)).thenReturn(null);

        // We need to mock getNativeType which is likely a method in the same class or superclass
        // Since it's not explicitly listed as a "method to mock" but used in the logic, 
        // we assume it's part of the class hierarchy.
        JSType unknownType = mock(JSType.class);
        when(prototypeObjectType.getNativeType(JSTypeNative.UNKNOWN_TYPE)).thenReturn(unknownType);

        // Act
        JSType result = prototypeObjectType.getPropertyType(property);

        // Assert
        assertEquals("Should return the native unknown type when slot is null", unknownType, result);
    }

    @Test
    public void testGetPropertyType_WhenSlotExists_ReturnsSlotType() {
        // Arrange
        String property = "existingProperty";
        StaticSlot<JSType> mockSlot = mock(StaticSlot.class);

        // Mock getSlot to return the mockSlot
        when(prototypeObjectType.getSlot(property)).thenReturn(mockSlot);
        // Mock the slot to return our specific mockType
        when(mockSlot.getType()).thenReturn(mockType);

        // Act
        JSType result = prototypeObjectType.getPropertyType(property);

        // Assert
        assertNotNull("Result should not be null", result);
        assertEquals("Should return the type provided by the slot", mockType, result);
    }
}
